package dev.syncidea.lab.tags;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class StableDistinctTest {
    @Test void keepsFirstOccurrenceAndExactEquality() {
        assertEquals(List.of("a", "b", "A", "", " "), StableDistinct.unique(List.of("a", "b", "a", "A", "", " ", "")));
    }
    @Test void handlesEmptyAndRepeatedValues() {
        assertEquals(List.of(), StableDistinct.unique(List.of()));
        assertEquals(List.of("x"), StableDistinct.unique(List.of("x", "x", "x")));
    }
    @Test void returnsIndependentImmutableResultWithoutChangingInput() {
        var input = new ArrayList<>(List.of("a", "a", "b"));
        var result = StableDistinct.unique(input);
        assertEquals(List.of("a", "a", "b"), input);
        input.clear();
        assertEquals(List.of("a", "b"), result);
        assertThrows(UnsupportedOperationException.class, () -> result.add("c"));
        assertThrows(UnsupportedOperationException.class, () -> result.set(0, "c"));
        assertThrows(UnsupportedOperationException.class, () -> result.remove(0));
    }
    @Test void rejectsNulls() {
        assertThrows(NullPointerException.class, () -> StableDistinct.unique(null));
        assertThrows(NullPointerException.class, () -> StableDistinct.unique(Arrays.asList("a", null)));
    }
}
